/**
 * @file BallFilterPresets.js
 * @brief Base Poké Ball filters (C++: class BallFilterPresets, static), read from
 * data/raw/ball-filter-presets-data.js (generated by tools/data/gen-balls.mjs).
 * Order = priority. A preset is locked: it cannot be deleted, renamed or have its options
 * edited; its ball, its place and its enabled state belong to the player.
 */
import { BALL_FILTER_PRESETS_TABLE } from '../raw/ball-filter-presets-data.js';

export class BallFilterPresets {
  /** @returns {string[]} Preset ids, in priority order */
  static ids() {
    return BALL_FILTER_PRESETS_TABLE.map((preset) => preset.id);
  }

  /**
   * @param {string} id
   * @returns {boolean}
   */
  static has(id) {
    return BALL_FILTER_PRESETS_TABLE.some((preset) => preset.id === id);
  }

  /**
   * @param {string} id
   * @returns {Object|null} Fresh copy of the preset options
   */
  static optionsOf(id) {
    const preset = BALL_FILTER_PRESETS_TABLE.find((entry) => entry.id === id);
    return preset ? { ...preset.options } : null;
  }

  /**
   * @param {string} id
   * @returns {string} Localization key of the preset name
   */
  static labelKey(id) {
    return `ball_filter_${id}`;
  }
}
